'use strict';

/**
 * One-time backfill for the 20 SanMar products already created in Shopify
 * before shopify.js linked variant->image (see src/shopify.js's
 * linkVariantImages). Without that link, Shopify's color swatches have no
 * per-variant image to switch to, so picking a color never changes the
 * product photo.
 *
 * Sources the intended color->image mapping from
 * data/processed/shopify_products_pilot.csv (already generated by
 * build-shopify-csv.js and confirmed to cover all 20 products) rather than
 * re-parsing the multi-hundred-MB raw EPDD file, which has a malformed
 * quote further down that breaks strict CSV parsing.
 *
 * Usage:
 *   node scripts/backfill-variant-images.js --dry-run
 *   node scripts/backfill-variant-images.js
 */

const fs = require('fs');
const path = require('path');
const { parse } = require('csv-parse/sync');
require('dotenv').config({ path: path.join(__dirname, '../.env') });

const { getClient, linkVariantImages, sleep } = require('../src/shopify');

const REQUEST_DELAY_MS = 600; // Shopify REST limit: ~2 req/s — same pacing as other scripts

const PILOT_CSV_FILE = path.join(__dirname, '../data/processed/shopify_products_pilot.csv');
const CREATED_MAP_FILE = path.join(__dirname, '../data/processed/created_products.json');

/**
 * Builds title -> variants[{option1, option2, image:{src}}] from the pilot
 * CSV, in the same shape src/shopify.js's linkVariantImages expects.
 */
function loadMappedProductsFromCsv(filePath) {
  const rows = parse(fs.readFileSync(filePath, 'utf8'), { columns: true, trim: true });

  const byTitle = new Map();
  let currentTitle = null;
  for (const row of rows) {
    if (row.Title) currentTitle = row.Title;
    if (!row['Option1 Value']) continue; // pure "extra image" row, no variant on it

    if (!byTitle.has(currentTitle)) byTitle.set(currentTitle, { title: currentTitle, variants: [] });
    byTitle.get(currentTitle).variants.push({
      option1: row['Option1 Value'],
      option2: row['Option2 Value'],
      image: row['Variant Image'] ? { src: row['Variant Image'] } : undefined,
    });
  }
  return byTitle;
}

async function main() {
  const dryRun = process.argv.includes('--dry-run');

  console.log('Loading color -> image mapping from shopify_products_pilot.csv...');
  const mappedByTitle = loadMappedProductsFromCsv(PILOT_CSV_FILE);
  console.log(`  ${mappedByTitle.size} products mapped\n`);

  const createdMap = JSON.parse(fs.readFileSync(CREATED_MAP_FILE, 'utf8'));
  const client = await getClient();

  let totalLinked = 0;
  let totalUnmatched = 0;
  let productsSkipped = 0;

  for (const [title, productId] of Object.entries(createdMap)) {
    const mapped = mappedByTitle.get(title);
    if (!mapped) {
      console.log(`  SKIP (not found in pilot CSV) — ${title}`);
      productsSkipped++;
      continue;
    }

    const res = await client.get(`/products/${productId}.json`, {
      params: { fields: 'id,title,images,variants' },
    });
    const live = res.data.product;

    if (dryRun) {
      // Dry-run reuses the same matching logic but only reports what it
      // would do — swap in a no-op client so linkVariantImages never PUTs.
      const preview = [];
      const noopClient = {
        put: async (url, body) => {
          preview.push(`${url} -> image_id ${body.variant.image_id}`);
        },
      };
      const { linked, unmatched } = await linkVariantImages(noopClient, live, mapped.variants);
      preview.forEach((line) => console.log(`    [dry-run] ${line}`));
      console.log(`  ${title} (id ${productId}) — would link: ${linked}, unmatched: ${unmatched}`);
      totalLinked += linked;
      totalUnmatched += unmatched;
    } else {
      const { linked, unmatched } = await linkVariantImages(client, live, mapped.variants);
      console.log(`  ${title} (id ${productId}) — linked: ${linked}, unmatched: ${unmatched}`);
      totalLinked += linked;
      totalUnmatched += unmatched;
    }

    await sleep(REQUEST_DELAY_MS);
  }

  console.log(
    `\nDone${dryRun ? ' (DRY RUN — no writes made)' : ''}. ` +
    `Linked: ${totalLinked} | Unmatched: ${totalUnmatched} | Products skipped: ${productsSkipped}`
  );
}

main().catch((err) => {
  console.error('Backfill error:', err.response ? JSON.stringify(err.response.data) : err.message);
  process.exit(1);
});
